import {
  getState,
  live,
  NetworkFailure,
  NetworkState,
  NetworkUnavailable
} from "@better-native/network"
import * as Effect from "effect/Effect"
import * as Schema from "effect/Schema"

const AvailableSnapshot = Schema.Struct({
  status: Schema.Literal("available"),
  state: NetworkState
})

const UnavailableSnapshot = Schema.Struct({
  status: Schema.Literal("unavailable"),
  method: Schema.String
})

const FailureSnapshot = Schema.Struct({
  status: Schema.Literal("failure"),
  method: Schema.String
})

export const NetworkSnapshot = Schema.Union(
  AvailableSnapshot,
  UnavailableSnapshot,
  FailureSnapshot
)

export type NetworkSnapshot = Schema.Schema.Type<typeof NetworkSnapshot>

export const readNetwork = getState.pipe(
  Effect.map((state) => ({
    status: "available" as const,
    state
  })),
  Effect.catchIf(
    (error) => Schema.is(NetworkUnavailable)(error),
    (error) =>
      Effect.succeed({
        status: "unavailable" as const,
        method: error.method
      })
  ),
  Effect.catchIf(
    (error) => Schema.is(NetworkFailure)(error),
    (error) =>
      Effect.succeed({
        status: "failure" as const,
        method: error.method
      })
  ),
  Effect.provide(live)
)

